-- Invented data, no client record: a theatre database as the step-1 code (2f6cc9b) wrote it. Generated by
-- importing packages/theatre/test/fixtures/invented-export.json, running --seed-missing, and creating one invented
-- administrator (boss@example.test), then dumping the file. Every address is @example.test.
CREATE TABLE _migrations (source TEXT PRIMARY KEY, hash TEXT, applied_at TEXT);
CREATE TABLE saved_view (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  source_type TEXT NOT NULL,
  source TEXT NOT NULL,
  skin TEXT NOT NULL DEFAULT 'table',
  filters TEXT NOT NULL DEFAULT '{}',
  sort TEXT NOT NULL DEFAULT '[]',
  group_by TEXT,
  visible_fields TEXT NOT NULL DEFAULT '[]',
  owner_id INTEGER,
  shared INTEGER NOT NULL DEFAULT 0,
  share_token TEXT,
  format TEXT NOT NULL DEFAULT 'html',
  public INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT
);
CREATE TABLE revision (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  entity TEXT NOT NULL,
  record_id INTEGER NOT NULL,
  field TEXT NOT NULL,
  old TEXT,
  new TEXT,
  actor_id INTEGER NOT NULL,
  at TEXT NOT NULL,
  batch_id TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT
);
CREATE TABLE batch (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  key TEXT NOT NULL,
  actor_id INTEGER NOT NULL,
  kind TEXT NOT NULL,
  at TEXT NOT NULL,
  undone_by TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT,
  UNIQUE (key)
);
CREATE TABLE account (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  email TEXT NOT NULL,
  role TEXT NOT NULL,
  subject_dataset TEXT,
  subject_id INTEGER,
  disabled_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT,
  CHECK (id > 0),
  CHECK (role IN ('administrator', 'editor', 'owner')),
  UNIQUE (email COLLATE NOCASE)
);
CREATE TABLE magic_link (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  account_id INTEGER NOT NULL REFERENCES account(id),
  token_hash TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  used_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT
);
CREATE TABLE auth_session (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  account_id INTEGER NOT NULL REFERENCES account(id),
  id_hash TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT
);
CREATE TABLE rate_limit (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  key TEXT NOT NULL,
  window_start INTEGER NOT NULL,
  count INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT,
  UNIQUE (key, window_start)
);
CREATE TABLE organisatie (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  naam TEXT NOT NULL,
  soort TEXT NOT NULL,
  adres TEXT,
  lat REAL,
  lng REAL,
  toegang TEXT,
  contact TEXT,
  parameters TEXT,
  legacy_post_id INTEGER,
  custom TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT
);
CREATE TABLE productie (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  titel TEXT NOT NULL,
  seizoen TEXT,
  status TEXT NOT NULL DEFAULT 'ontwikkeling',
  organisatie_id INTEGER REFERENCES organisatie(id),
  site_ref TEXT,
  legacy_post_id INTEGER,
  custom TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT
);
CREATE TABLE speelreeks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  productie_id INTEGER NOT NULL REFERENCES productie(id),
  naam TEXT NOT NULL,
  locatie_id INTEGER REFERENCES organisatie(id),
  start_datum TEXT NOT NULL,
  eind_datum TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'optie',
  custom TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT
);
CREATE TABLE activiteit (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  productie_id INTEGER NOT NULL REFERENCES productie(id),
  speelreeks_id INTEGER REFERENCES speelreeks(id),
  soort TEXT NOT NULL,
  omschrijving TEXT,
  datum TEXT NOT NULL,
  start_at TEXT,
  eind_at TEXT,
  plandag TEXT NOT NULL,
  locatie_id INTEGER REFERENCES organisatie(id),
  plaats TEXT,
  status TEXT NOT NULL DEFAULT 'optie',
  verrekening_default TEXT,
  bron TEXT NOT NULL DEFAULT 'plan',
  notities TEXT,
  legacy_post_id INTEGER,
  custom TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT
);
CREATE TABLE persoon (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  voornaam TEXT NOT NULL,
  achternaam TEXT NOT NULL,
  weergavenaam TEXT NOT NULL,
  email TEXT,
  telefoon TEXT,
  organisatie_id INTEGER REFERENCES organisatie(id),
  contract_type TEXT,
  dietary TEXT,
  actief INTEGER NOT NULL DEFAULT 1,
  legacy_post_id INTEGER,
  custom TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT
);
CREATE TABLE toewijzing (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  activiteit_id INTEGER NOT NULL REFERENCES activiteit(id),
  persoon_id INTEGER REFERENCES persoon(id),
  naam TEXT,
  state TEXT NOT NULL DEFAULT 'uitgenodigd',
  notitie TEXT,
  legacy_post_id INTEGER,
  custom TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT
);
CREATE TABLE beschikbaarheid (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  persoon_id INTEGER NOT NULL REFERENCES persoon(id),
  start_at TEXT NOT NULL,
  eind_at TEXT NOT NULL,
  reden TEXT,
  legacy_post_id INTEGER,
  custom TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT
);
CREATE TABLE rol (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  naam TEXT NOT NULL,
  categorie TEXT NOT NULL,
  standaard_verrekening TEXT,
  dagtarief REAL,
  uurtarief REAL,
  kleur TEXT,
  custom TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT
);
CREATE TABLE sjabloon (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  naam TEXT NOT NULL,
  items TEXT NOT NULL,
  custom TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT
);
CREATE INDEX revision_entity_record_id_idx ON revision (entity, record_id);
CREATE INDEX revision_batch_id_idx ON revision (batch_id);
CREATE INDEX magic_link_token_hash_idx ON magic_link (token_hash);
CREATE INDEX auth_session_id_hash_idx ON auth_session (id_hash);
CREATE INDEX rate_limit_window_start_idx ON rate_limit (window_start);
CREATE INDEX activiteit_plandag_idx ON activiteit (plandag);
CREATE INDEX toewijzing_persoon_id_idx ON toewijzing (persoon_id);
CREATE INDEX toewijzing_activiteit_id_idx ON toewijzing (activiteit_id);
CREATE VIEW productie_dag AS SELECT MIN(a.id) AS id, a.productie_id, p.titel AS productie, a.plandag, COUNT(*) AS activiteiten, SUM(a.soort = 'voorstelling') AS voorstellingen, SUM(a.soort = 'repetitie') AS repetities, SUM(a.soort = 'opbouw') AS opbouw, SUM(a.soort = 'afbouw') AS afbouw, SUM(a.soort = 'reis') AS reis, SUM(a.soort = 'overnachting') AS overnachting, SUM(a.soort = 'maaltijd') AS maaltijd, SUM(a.soort = 'vergadering') AS vergadering, SUM(a.soort = 'andere') AS andere FROM activiteit a JOIN productie p ON p.id = a.productie_id WHERE a.deleted_at IS NULL GROUP BY a.productie_id, a.plandag;
CREATE VIEW dagplanning AS SELECT a.id AS id, a.id AS activiteit_id, a.productie_id, p.titel AS productie, a.omschrijving, a.soort, a.datum, a.start_at, a.plandag, a.status, COALESCE(a.locatie_id, s.locatie_id) AS locatie_id, CASE WHEN a.locatie_id IS NOT NULL THEN 'eigen' WHEN s.locatie_id IS NOT NULL THEN 'speelreeks' END AS locatie_bron FROM activiteit a JOIN productie p ON p.id = a.productie_id LEFT JOIN speelreeks s ON s.id = a.speelreeks_id AND s.deleted_at IS NULL WHERE a.deleted_at IS NULL;
CREATE VIEW voorstellingen AS SELECT a.id, p.titel AS productie, a.datum, substr(a.start_at, 12, 5) AS start, o.naam AS venue, o.adres FROM activiteit a JOIN productie p ON p.id = a.productie_id AND p.deleted_at IS NULL LEFT JOIN speelreeks s ON s.id = a.speelreeks_id AND s.deleted_at IS NULL LEFT JOIN organisatie o ON o.id = COALESCE(a.locatie_id, s.locatie_id) AND o.deleted_at IS NULL WHERE a.deleted_at IS NULL AND a.soort = 'voorstelling' AND a.status = 'bevestigd';
